@IsTest private class LocalZoneNativeProbeTest {
 private static void observe(String id, Datetime stamp, Boolean labels) {
  Map<String,Object> cell=new Map<String,Object>{'id'=>id,'epoch'=>stamp.getTime(),'date'=>String.valueOf(stamp.date()),'gmt'=>stamp.formatGmt('yyyy-MM-dd HH:mm:ss.SSS'),'local'=>stamp.format('yyyy-MM-dd HH:mm:ss.SSS'),'calendar'=>stamp.format('yyyy-MM-dd')};
  if(labels) {cell.put('zone',stamp.format('z'));cell.put('longZone',stamp.format('zzzz'));cell.put('offset',stamp.format('Z'));}
  cells.add(cell);
 }
 private static List<Object> cells=new List<Object>();
 @IsTest static void collect() {
  User actor=new User(LastName='Owned Format',Alias='fmtprobe',Username='ownedformat'+Datetime.now().getTime()+'@example.invalid',Email='ownedformat@example.invalid',TimeZoneSidKey='Pacific/Kiritimati',LocaleSidKey='en_US',EmailEncodingKey='UTF-8',LanguageLocaleKey='en_US',ProfileId=UserInfo.getProfileId());
  System.runAs(actor) {
   observe('F01',Datetime.newInstance(2026,2,1),true);
   observe('F02',Datetime.newInstance(0),true);
   observe('F03',(Datetime)JSON.deserialize('"1994-12-31T09:59:59.999Z"',Datetime.class),true);
   observe('F04',(Datetime)JSON.deserialize('"1994-12-31T10:00:00.000Z"',Datetime.class),true);
   observe('F05',Datetime.newInstance(1735689600123L),true);
   observe('F06',Datetime.newInstance(Date.newInstance(2024,2,29),Time.newInstance(0,0,0,123)),false);
  }
  User utcActor=actor.clone(false,false,false,false);utcActor.Username='ownedutc'+Datetime.now().getTime()+'@example.invalid';utcActor.TimeZoneSidKey='GMT';
  System.runAs(utcActor) {observe('F07',Datetime.newInstance(0),true);observe('F08',Datetime.newInstance(1735689600123L),false);}
  System.assert(false,'NATIVE_FORMAT|'+JSON.serialize(cells));
 }
}

